import numpy as np
import xarray as xr
from satpy.readers.fci_l1c_nc import FCIL1cNCFileHandler

def test_drop_fill_value():
    # Mocking the necessary components for FCIL1cNCFileHandler
    class MockHandler(FCIL1cNCFileHandler):
        def __init__(self, *args, **kwargs):
            pass
        def calibrate_counts_to_physical_quantity(self, data, key):
            # Just return the data as is, but ensure it's a float32 DataArray
            return data.astype(np.float32)

    handler = MockHandler()

    # Case 1: Calibration is brightness_temperature, _FillValue should be dropped
    data = xr.DataArray(np.array([1.0, 2.0]), attrs={"_FillValue": 65535})
    key = {"calibration": "brightness_temperature", "name": "ir_105"}
    result = handler.calibrate(data, key)
    assert "_FillValue" not in result.attrs, " _FillValue should be dropped for brightness_temperature"

    # Case 2: Calibration is counts, _FillValue should be kept
    data = xr.DataArray(np.array([1.0, 2.0]), attrs={"_FillValue": 65535})
    key = {"calibration": "counts", "name": "ir_105"}
    result = handler.calibrate(data, key)
    assert "_FillValue" in result.attrs, "_FillValue should be kept for counts"

if __name__ == "__main__":
    try:
        test_drop_fill_value()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)
    except Exception as e:
        print(f"An error occurred: {e}")
        exit(1)
